import re
import sys


def main():
    text = sys.stdin.read()
    paragraphs = [p.strip() for p in text.split('\n\n') if p.strip()]
    paragraphs_count = len(paragraphs)

    sentences_per_paragraph = []
    current_sentences = []
    in_sentence = False
    for line in text.split('\n'):
        line = line.strip()
        if not line:
            if current_sentences:
                sentences_per_paragraph.append(current_sentences)
                current_sentences = []
                in_sentence = False
        else:
            if not in_sentence:
                sentence_end = False
                for i, char in enumerate(line):
                    if char in ['.', '!', '?']:
                        if i == len(line) - 1:
                            sentence_end = True
                        else:
                            next_char = line[i + 1]
                            if next_char.isspace():
                                sentence_end = True
                            elif next_char in ['M', 'r', 'D', 's']:
                                if line.startswith(('Mr', 'Mrs', 'Dr', 'St'), case=False):
                                    sentence_end = False
                                else:
                                    sentence_end = True
                    if sentence_end:
                        current_sentences.append(line[:i])
                if current_sentences:
                    sentences_per_paragraph.append(current_sentences)
                    current_sentences = []
                    in_sentence = True
            else:
                current_sentences.append(line)
    if current_sentences:
        sentences_per_paragraph.append(current_sentences)
    sentences_count = sum([len(s) for s_list in sentences_per_paragraph for s in s_list if s])

    words = re.findall(r"[A-Za-z0-9'-]+", text)
    words_count = len(words)
    longest_word = max(words, key=len) if words else "-"

    print("paragraphs", paragraphs_count)
    print("sentences", sentences_count)
    print("words", words_count)
    print("longest", longest_word)


if __name__ == "__main__":
    main()
